function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    fetch(url).then(r => r.json())
      .then(setData).finally(() => setLoading(false));
  }, [url]);
  return { data, loading };
}

